#include "cJSON.h"
#include "lodepng.h"

static double *load_array(cJSON *arr, int *outn) {
    int n = cJSON_GetArraySize(arr);
    double *out = (double *)malloc(sizeof(double) * (n > 0 ? n : 1));
    if (!out) { fprintf(stderr, "oom\n"); exit(1); }
    int i = 0;
    for (cJSON *e = arr->child; e; e = e->next) out[i++] = e->valuedouble;
    *outn = i;
    return out;
}

static double *linear(const double *W, const double *B, int in_f, int out_f, const double *x) {
    double *y = (double *)malloc(sizeof(double) * out_f);
    for (int o = 0; o < out_f; o++) {
        double s = B[o];
        const double *row = W + (size_t)o * in_f;
        for (int i = 0; i < in_f; i++) s += row[i] * x[i];
        y[o] = s;
    }
    return y;
}

static void relu(double *v, int n) { for (int i = 0; i < n; i++) if (v[i] < 0) v[i] = 0; }

static double sample(const double *img, int w, int h, double x, double y) {
    if (x < 0) x = 0; if (y < 0) y = 0;
    if (x > w-1) x = w-1; if (y > h-1) y = h-1;
    int x0 = (int)x, y0 = (int)y, x1 = x0+1, y1 = y0+1;
    if (x1 >= w) x1 = w-1;
    if (y1 >= h) y1 = h-1;
    double fx = x - x0, fy = y - y0;
    double top = img[y0*w + x0]*(1.0-fx) + img[y0*w + x1]*fx;
    double bot = img[y1*w + x0]*(1.0-fx) + img[y1*w + x1]*fx;
    return top*(1.0-fy) + bot*fy;
}

int main(int argc, char **argv) {
    if (argc < 3) { fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]); return 1; }
    const char *weights_path = argv[1];
    const char *image_path = argv[2];

    /* ---- load weights ---- */
    FILE *f = fopen(weights_path, "rb");
    if (!f) { fprintf(stderr, "cannot open weights\n"); return 1; }
    fseek(f, 0, SEEK_END); long len = ftell(f); fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(len + 1);
    if (fread(buf, 1, len, f) != (size_t)len) { fprintf(stderr, "read err\n"); return 1; }
    buf[len] = 0;
    fclose(f);
    cJSON *root = cJSON_Parse(buf);
    if (!root) { fprintf(stderr, "json parse err\n"); return 1; }

    cJSON *l1 = cJSON_GetObjectItemCaseSensitive(root, "input_layer");
    cJSON *l2 = cJSON_GetObjectItemCaseSensitive(root, "hidden_layer");
    cJSON *l3 = cJSON_GetObjectItemCaseSensitive(root, "output_layer");
    int n1w, n1b, n2w, n2b, n3w, n3b;
    double *w1 = load_array(cJSON_GetObjectItemCaseSensitive(l1, "weight"), &n1w);
    double *b1 = load_array(cJSON_GetObjectItemCaseSensitive(l1, "bias"), &n1b);
    double *w2 = load_array(cJSON_GetObjectItemCaseSensitive(l2, "weight"), &n2w);
    double *b2 = load_array(cJSON_GetObjectItemCaseSensitive(l2, "bias"), &n2b);
    double *w3 = load_array(cJSON_GetObjectItemCaseSensitive(l3, "weight"), &n3w);
    double *b3 = load_array(cJSON_GetObjectItemCaseSensitive(l3, "bias"), &n3b);

    int in1 = n1w / n1b;      /* 784 */
    int h1  = n1b;            /* 16  */
    int h2  = n2b;            /* 16  */
    int out = n3b;            /* 10  */
    /* sanity */
    if (n2w != h1*h2 || n3w != h2*out) { fprintf(stderr, "dim mismatch\n"); return 1; }

    /* ---- load image ---- */
    unsigned char *img = NULL;
    unsigned w = 0, h = 0;
    unsigned err = lodepng_decode32_file(&img, &w, &h, image_path);
    if (err) { fprintf(stderr, "png err %u: %s\n", err, lodepng_error_text(err)); return 1; }

    double *gray = (double *)malloc(sizeof(double) * w * h);
    for (unsigned i = 0; i < w*h; i++) {
        gray[i] = 0.299*img[i*4] + 0.587*img[i*4+1] + 0.114*img[i*4+2];
    }

    int target = (int)(0.5 + sqrt((double)in1));
    double *input = (double *)malloc(sizeof(double) * in1);
    if (w == target && h == target) {
        memcpy(input, gray, sizeof(double) * in1);
    } else {
        for (int y = 0; y < target; y++)
            for (int x = 0; x < target; x++) {
                double sx = (x + 0.5) * (double)w / target - 0.5;
                double sy = (y + 0.5) * (double)h / target - 0.5;
                input[y*target + x] = sample(gray, (int)w, (int)h, sx, sy);
            }
    }
    free(gray); free(img);

    /* ---- normalize (MNIST standard) ---- */
    for (int i = 0; i < in1; i++) input[i] = (input[i] - 127.5) / 128.0;

    /* ---- forward ---- */
    double *a1 = linear(w1, b1, in1, h1, input); relu(a1, h1);
    double *a2 = linear(w2, b2, h1, h2, a1);     relu(a2, h2);
    double *o  = linear(w3, b3, h2, out, a2);

    int best = 0;
    for (int i = 1; i < out; i++) if (o[i] > o[best]) best = i;

    printf("%d\n", best);

    FILE *pf = fopen("prediction.txt", "w");
    if (pf) { fprintf(pf, "%d\n", best); fclose(pf); }

    return 0;
}
